import time

from taf.rfrl.procedures.resources.python.logger import log_warning
from taf.rfrl.procedures.resources.python.scout.exceptions import ScoutAPIError


def retry_request_on_failure(func, retries=3, delay=30):

    def wrapper(*args, **kwargs):
        for retry in range(retries):
            try:
                return func(*args, **kwargs)
            except ScoutAPIError as e:

                log_warning(f"[{retry+1}/{retries}] Executing {func.__name__} failed. {e}")
                if retry < retries - 1:
                    time.sleep(delay)

        raise ScoutAPIError(f"Retry limit exceeded while executing {func.__name__}")

    return wrapper
